xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;700;900&display=swap');

.xt-root {
    --xt-bg: #fff;
    --xt-text: #333;
    --xt-text-sub: #666;
    --xt-text-muted: #999;
    --xt-accent: #0066cc;
    --xt-accent-bg: rgba(0,102,204,0.06);
    --xt-border: #8a8a8a;
    --xt-radius: 0px;
    --xt-font: 'Noto Sans SC', "SimSun", "宋体", sans-serif;
    background: #fff;
    border: 2px solid #8a8a8a;
    box-shadow: none;
    max-width: 400px;
    padding: 0;
    overflow: hidden;
    border-radius: 0;
}

/* ═══════ 顶栏：论坛导航条 ═══════ */
.xt-header {
    background: linear-gradient(180deg, #e8edf2 0%, #d0d8e2 100%);
    border-bottom: 2px solid #8a8a8a;
    padding: 8px 12px;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 8px;
}
.xt-avatar {
    width: 36px !important;
    height: 36px !important;
    border-color: #8a8a8a;
    border-width: 2px;
    border-radius: 0 !important;
}
.xt-name {
    color: #0044aa;
    font-size: 14px;
    font-weight: 900;
    letter-spacing: 0.5px;
    text-decoration: underline;
}

/* ═══════ 帖子标题（topic） ═══════ */
.xt-section-0 {
    margin: 0;
    padding: 0;
    background: #fafafa;
    box-shadow: none;
    border-radius: 0;
}
.xt-section-0 .xt-section-title { display: none; }
.xt-section-0 .xt-section-body {
    background: transparent;
    border: none !important;
    padding: 12px 14px 2px;
    font-size: 17px;
    font-weight: 900;
    color: #cc0000;
    letter-spacing: 1px;
    line-height: 1.5;
}
/* 标题前面加【】装饰 */
.xt-section-0 .xt-section-body::before {
    content: "【";
    color: #cc0000;
}
.xt-section-0 .xt-section-body::after {
    content: "】";
    color: #cc0000;
}

/* ═══════ 时间戳通用 ═══════ */
.xt-text {
    padding: 2px 14px;
    font-size: 11px;
    color: #666;
    background: transparent;
    border-radius: 0;
    letter-spacing: 0.5px;
    font-weight: 700;
}

/* 第1个时间戳：楼主发帖时间 */
.xt-text:nth-of-type(1) {
    padding: 2px 14px 6px;
    color: #888;
}
.xt-text:nth-of-type(1)::before {
    content: "发表于 ";
    font-weight: 400;
}

/* ═══════ 分隔线 ═══════ */
.xt-divider {
    border-top: 1px dashed #bbb !important;
    background: none !important;
    height: auto !important;
    margin: 0 !important;
}

/* ═══════ section 共用 ═══════ */
.xt-section {
    margin: 0;
    padding: 0;
    background: transparent;
    box-shadow: none;
    border-radius: 0;
}
.xt-section-title { display: none; }
.xt-section-body {
    background: transparent;
    border: none !important;
    padding: 8px 14px 10px;
    font-size: 13px;
    line-height: 2;
    letter-spacing: 0.3px;
    color: #333;
}

/* ═══════ 1楼：楼主·现在 ═══════ */
.xt-section-1 {
    position: relative;
    background: #fff;
}
.xt-section-1::before {
    content: "1楼 · 楼主";
    position: absolute;
    top: 10px;
    right: 10px;
    font-size: 10px;
    color: #fff;
    background: #cc0000;
    padding: 2px 10px;
    font-weight: 900;
    letter-spacing: 1px;
    border-radius: 0;
}
.xt-section-1 .xt-section-body {
    color: #222;
    font-weight: 400;
    font-size: 14px;
}

/* ═══════ 2楼：过去 ═══════ */
.xt-text:nth-of-type(2) {
    padding: 10px 14px 0;
    font-size: 13px;
    color: #0044aa;
    font-weight: 900;
    text-decoration: underline;
}
.xt-text:nth-of-type(3) {
    padding: 0 14px 4px;
    color: #888;
}
.xt-text:nth-of-type(3)::before {
    content: "发表于 ";
    font-weight: 400;
}
.xt-section-2 {
    position: relative;
    background: #f8f8f6;
}
.xt-section-2::before {
    content: "2楼";
    position: absolute;
    top: 10px;
    right: 10px;
    font-size: 10px;
    color: #888;
    background: #e8e8e8;
    padding: 2px 10px;
    font-weight: 900;
    letter-spacing: 1px;
}
.xt-section-2 .xt-section-body {
    color: #777;
    font-style: italic;
    font-weight: 400;
    border-left: 3px solid #aab8cc !important;
    margin: 0 14px;
    padding: 6px 12px;
    background: #f0f2f5;
}

/* ═══════ 3楼：未来 ═══════ */
.xt-text:nth-of-type(4) {
    padding: 10px 14px 0;
    font-size: 13px;
    color: #6644aa;
    font-weight: 900;
    text-decoration: underline;
}
.xt-text:nth-of-type(5) {
    padding: 0 14px 4px;
    color: #888;
}
.xt-text:nth-of-type(5)::before {
    content: "发表于 ";
    font-weight: 400;
}
.xt-section-3 {
    position: relative;
    background: #fff;
}
.xt-section-3::before {
    content: "3楼";
    position: absolute;
    top: 10px;
    right: 10px;
    font-size: 10px;
    color: #888;
    background: #e8e8e8;
    padding: 2px 10px;
    font-weight: 900;
    letter-spacing: 1px;
}
.xt-section-3 .xt-section-body {
    color: #7766aa;
    font-weight: 400;
    border-left: 3px solid #c8c0dd !important;
    margin: 0 14px;
    padding: 6px 12px;
    background: #f6f4fa;
}

/* ═══════ 底部 ═══════ */
.xt-footer {
    background: linear-gradient(180deg, #e8edf2 0%, #d0d8e2 100%);
    border-top: 2px solid #8a8a8a;
    color: #888;
    font-size: 10px;
    letter-spacing: 1px;
    padding: 8px 14px;
    text-align: center;
}

